function demoIllustration(i){const art=Object.hasOwn(sampleArt,i.title)?sampleArt[i.title]:null;return i.demo&&art?`<span class="demo-art" style="background-color:${art[0]}" aria-hidden="true"><svg viewBox="0 0 220 190" xmlns="http://www.w3.org/2000/svg">${art[1]}</svg></span>`:''}
function itemPhoto(i){return i.image?`<img src="${E(i.image)}" alt="${E(i.title)}" loading="lazy" referrerpolicy="no-referrer">`:(demoIllustration(i)||`<span class="placeholder" style="background-color:${catInfo(i.category)[2]}">${icon(catInfo(i.category)[1])}</span>`)}
function hearts(n){return `<span class="hearts" aria-label="Сила желания ${n} из 5" title="Сила желания ${n} из 5">${'♥'.repeat(n)}${'♡'.repeat(5-n)}</span>`}
function itemCard(i){const c=convert(i.price,i.currency),host=i.url?new URL(i.url).hostname.replace(/^www\./,''):'';return `<article class="product-card"><div class="product-photo" data-action="detail" data-id="${E(i.id)}">${itemPhoto(i)}<span class="urgency ${i.urgency>=4?'high':''}">${i.status==='bought'?'Исполнено ✓':E(urgency[i.urgency-1])}</span><button class="icon-btn fav ${i.favorite?'active':''}" data-action="favorite" data-id="${E(i.id)}" aria-pressed="${i.favorite}" aria-label="${i.favorite?'Убрать из избранного':'В избранное'}">${icon('heart')}</button></div><div class="product-body"><div class="product-meta"><span>${E(i.category)}</span><span>${E(host||statuses[i.status])}</span></div><button class="product-title" data-action="detail" data-id="${E(i.id)}">${E(i.title)}</button><div class="price">${money(i.price,i.currency)}</div><div class="converted">${i.currency!==state.settings.base&&i.price!=null?(c==null?'Нет курса для пересчёта':'≈ '+money(c)):i.quantity>1?`${i.quantity} шт.`:'&nbsp;'}</div><div class="card-bottom">${hearts(i.rating)}<div class="card-actions"><button class="icon-btn" data-action="edit" data-id="${E(i.id)}" title="Редактировать" aria-label="Редактировать">${icon('edit')}</button><button class="icon-btn" data-action="toggle-bought" data-id="${E(i.id)}" title="${i.status==='bought'?'Вернуть в желания':'Отметить купленным'}" aria-label="${i.status==='bought'?'Вернуть в желания':'Отметить купленным'}">${icon(i.status==='bought'?'refresh':'check')}</button>${i.url?`<a class="icon-btn" href="${E(i.url)}" target="_blank" rel="noopener noreferrer" aria-label="Открыть товар" title="Открыть товар">${icon('external')}</a>`:''}</div></div></div></article>`}
function empty(filtered=false){return `<div class="empty"><span class="empty-icon">${icon(filtered?'search':'heart')}</span><h3>${filtered?'Ничего не нашлось':'Здесь будут твои желания'}</h3><p>${filtered?'Попробуй изменить фильтры или поиск.':'Добавь первую маленькую мечту — даже самую простую.'}</p><button class="btn primary" data-action="${filtered?'reset-filters':'add'}">${icon(filtered?'refresh':'plus')}${filtered?'Сбросить фильтры':'Добавить желание'}</button>${!filtered&&state.items.length===0?'<button class="btn" data-action="demo">Посмотреть пример</button>':''}</div>`}
function opt(values,selected){return values.map(x=>{const [v,l]=Array.isArray(x)?x:[x,x];return `<option value="${E(v)}" ${String(v)===String(selected)?'selected':''}>${E(l)}</option>`}).join('')}
function toolbar(items){const cats=[...new Set(items.map(i=>i.category))];return `<div class="toolbar"><label class="search">${icon('search')}<input id="search" type="text" placeholder="Найти желание…" value="${E(query)}" aria-label="Поиск"></label><select id="sort" aria-label="Сортировка">${opt([['recent','Сначала новые'],['rating','Самые желанные'],['urgency','Самые срочные'],['low','Цена ↑'],['high','Цена ↓'],['date','По дате покупки']],sort)}</select><select id="group" aria-label="Группировка">${opt([['none','Без групп'],['category','По категориям'],['list','По коллекциям'],['currency','По валютам'],['urgency','По срочности']],group)}</select><select id="status-filter" aria-label="Статус">${opt([['','Все статусы'],...Object.entries(statuses)],statusFilter)}</select><div class="toggle"><button class="icon-btn ${state.settings.view==='grid'?'active':''}" data-action="view-grid" aria-label="Сетка" aria-pressed="${state.settings.view==='grid'}">${icon('grid')}</button><button class="icon-btn ${state.settings.view==='list'?'active':''}" data-action="view-list" aria-label="Список" aria-pressed="${state.settings.view==='list'}">${icon('list')}</button></div></div><div class="chips"><button class="chip ${!category?'active':''}" data-category="" aria-pressed="${!category}">Все категории</button>${cats.map(c=>`<button class="chip ${category===c?'active':''}" data-category="${E(c)}" aria-pressed="${category===c}">${E(c)}</button>`).join('')}</div><div id="products"></div>`}
function sourceItems(){let a=state.items;if(page==='bought')return a.filter(i=>i.status==='bought');a=a.filter(i=>i.status!=='bought');if(page==='favorites')a=a.filter(i=>i.favorite);if(currentList())a=a.filter(i=>i.listId===currentList().id);return a}
function filteredItems(){const q=query.trim().toLowerCase();let a=sourceItems().filter(i=>(!category||i.category===category)&&(!statusFilter||i.status===statusFilter)&&(!q||[i.title,i.category,i.description,i.notes,i.variant,i.url].join(' ').toLowerCase().includes(q)));const price=i=>convert(i.price==null?null:i.price*i.quantity+(i.shipping||0),i.currency);return a.sort((x,y)=>{if(sort==='rating')return y.rating-x.rating;if(sort==='urgency')return y.urgency-x.urgency;if(sort==='date')return (x.date||'9999').localeCompare(y.date||'9999');if(sort==='low'||sort==='high'){const p=price(x),q=price(y);return p==null?(q==null?0:1):q==null?-1:sort==='low'?p-q:q-p}return y.created-x.created})}
function renderProducts(){const el=$('#products');if(!el)return;const a=filteredItems();if(!a.length){el.innerHTML=empty(!!(query||category||statusFilter)||sourceItems().length>0);return}const grid=items=>`<div class="product-grid ${state.settings.view==='list'?'list':''}">${items.map(itemCard).join('')}</div>`;if(group==='none'){el.innerHTML=grid(a);return}const m=new Map();for(const i of a){let k=group==='category'?i.category:group==='currency'?i.currency:group==='urgency'?urgency[i.urgency-1]:state.lists.find(l=>l.id===i.listId)?.name||'Без коллекции';if(!m.has(k))m.set(k,[]);m.get(k).push(i)}el.innerHTML=[...m].map(([k,v])=>`<section class="group"><h3 class="group-heading">${E(k)} <span class="muted">· ${v.length} · ${totalLabel(total(v),v.length)}</span></h3>${grid(v)}</section>`).join('')}
function render(){sidebar();let html='';const demo=state.items.some(i=>i.demo)?'<div class="demo-banner"><span>Демонстрационный список · можно удалить и начать свой.</span><button class="btn" data-action="remove-demo">Удалить пример</button></div>':'';if(page==='home'){html=hero(state.settings.name?`Привет, ${state.settings.name}!`:'Мои маленькие мечты','Место для всего, что делает жизнь чуть красивее.')+demo+quick()+stats()+`<div class="section-head"><div><h2>Мои коллекции</h2><p class="section-caption">Собери любимые вещи по темам.</p></div><button class="btn ghost" data-page="collections">Все ${icon('external')}</button></div>`+collectionTiles()+`<div class="section-head"><div><h2>Мои желания</h2><p class="section-caption">${sourceItems().length} в списке · ${E(fxText())}</p></div><button class="btn" data-action="fx">${icon('refresh')} Курсы</button></div>`+toolbar(sourceItems())}else if(page==='collections'){html=hero('Мои коллекции','Любимые вещи, собранные по настроению.')+collectionTiles()+`<div class="panel"><h2>Управление коллекциями</h2>${state.lists.length?state.lists.map(l=>`<div class="collection-manage"><span class="list-dot" style="background:${l.color}"></span><strong>${E(l.name)}</strong><small>${state.items.filter(i=>i.listId===l.id).length} желаний</small><button class="icon-btn" data-action="edit-list" data-id="${E(l.id)}" aria-label="Редактировать">${icon('edit')}</button><button class="icon-btn" data-action="delete-list" data-id="${E(l.id)}" aria-label="Удалить">${icon('trash')}</button></div>`).join(''):'<p>Создай первую коллекцию.</p>'}</div>`}else if(page==='settings'){html=hero('Настройки','Сделай это пространство своим.')+`<div class="panel mobile-shortcuts"><h2>Другие разделы</h2><div class="panel-actions" style="margin-top:12px"><button class="btn" data-page="favorites">${icon('heart')} Избранное</button><button class="btn" data-page="stats">${icon('chart')} Статистика</button></div></div><div class="panel"><h2>Персонализация</h2><form id="settings-form"><div class="setting-row"><label for="display-name">Как к тебе обращаться?</label><input id="display-name" name="name" type="text" maxlength="60" value="${E(state.settings.name)}" placeholder="Имя"></div><div class="setting-row"><label for="base">Основная валюта<small>В ней считаются суммы и бюджет.</small></label><select id="base" name="base">${opt([...new Set([...currencies,...Object.keys(state.fx?.rates||{}),state.settings.base])],state.settings.base)}</select></div><div class="setting-row"><label for="budget">Бюджет<small>В основной валюте. При её смене введи бюджет заново.</small></label><input id="budget" type="number" name="budget" min="0" step="0.01" value="${state.settings.budget??''}" placeholder="Не задан"></div><button class="btn primary" type="submit">Сохранить настройки</button></form></div><div class="panel"><h2>Курсы валют</h2><p>${E(fxText())}. Источник публикует ориентировочные курсы раз в день; комиссии банка не включены.</p><button class="btn" data-action="fx">${icon('refresh')} Обновить</button></div><div class="panel"><h2>Данные и приватность</h2><p>Желания хранятся в этом браузере. Они не синхронизируются автоматически между устройствами. Сохрани резервную копию перед очисткой браузера. Ссылка для обмена содержит снимок списка, а не доступ к аккаунту.</p><div class="panel-actions"><button class="btn" data-action="export">${icon('download')} Экспорт JSON</button><button class="btn" data-action="import-backup">${icon('upload')} Импорт JSON</button><button class="btn" data-action="share">${icon('share')} Поделиться</button><button class="btn danger" data-action="clear">Удалить все желания</button></div></div><div class="panel"><h2>Возможности импорта</h2><p>Автоимпорт использует публичные метаданные товара, если сайт магазина их отдаёт. При блокировке или неполных данных можно заполнить карточку вручную.</p></div>`}else if(page==='stats'){const a=state.items.filter(i=>i.status!=='bought'),t=total(a),budget=state.settings.budget;const cat=[...new Set(a.map(i=>i.category))].map(c=>[c,total(a.filter(i=>i.category===c))]).sort((x,y)=>y[1].sum-x[1].sum);html=hero('Мечты в цифрах','Планируй покупки и радуйся исполненным желаниям.')+stats()+`<div class="panel"><h2>Бюджет желаний</h2><p>${budget==null?'Бюджет пока не установлен.':`Бюджет ${money(budget)} · ${t.sum>budget?'Превышение':'Остаток'} ${money(Math.abs(budget-t.sum))}${t.unknown?' · неполная сумма':''}`}</p>${budget!=null?`<div class="progress"><span style="width:${budget>0?Math.min(100,t.sum/budget*100):t.sum>0?100:0}%"></span></div>`:''}<button class="btn" data-page="settings">Настроить бюджет</button></div><div class="panel"><h2>Расходы по категориям</h2><p>Только активные желания с известной ценой и курсом.</p><div class="bars">${cat.map(([c,v])=>`<div class="bar-row"><span>${E(c)}</span><div class="bar"><span style="width:${t.sum?v.sum/t.sum*100:0}%"></span></div><strong>${money(v.sum)}${v.unknown?'*':''}</strong></div>`).join('')||'<span class="muted">Пока нет данных.</span>'}</div></div><div class="panel"><h2>Уровень желания</h2><div class="bars">${[5,4,3,2,1].map(n=>{const count=a.filter(i=>i.rating===n).length;return `<div class="bar-row">${hearts(n)}<div class="bar"><span style="width:${a.length?count/a.length*100:0}%"></span></div><strong>${count}</strong></div>`}).join('')}</div></div>`}else{const a=sourceItems(),t=total(a);html=hero(currentList()?.name||({all:'Все желания',favorites:'Самое любимое',bought:'Исполненные мечты'}[page]),page==='bought'?'Маленькие радости, которые уже стали реальностью.':`${a.length} желаний · ${totalLabel(t,a.length)}${t.unknown?' · не всё посчитано':''}`)+demo+`<div class="section-head"><p class="section-caption">${E(fxText())}</p><div class="right">${currentList()?`<button class="btn" data-action="edit-list" data-id="${E(currentList().id)}">${icon('edit')} Коллекция</button>`:''}<button class="btn" data-action="fx">${icon('refresh')} Курсы</button><button class="btn primary" data-action="add">${icon('plus')} Добавить</button></div></div>`+toolbar(a)}$('#main-content').innerHTML=html;renderProducts();}
const modal=$('#modal');let modalEpoch=0;
function showModal(title,sub,body,actions=''){modalEpoch++;$('#modal-content').innerHTML=`<div class="modal-head"><div><h2 id="modal-title">${E(title)}</h2><p id="modal-description">${E(sub)}</p></div><button class="icon-btn" data-action="close" aria-label="Закрыть">${icon('close')}</button></div><div class="modal-body">${body}</div>${actions?`<div class="modal-actions">${actions}</div>`:''}`;if(!modal.open)modal.showModal();modal.scrollTop=0;return modalEpoch}
function closeModal(){modal.close();modalEpoch++}modal.addEventListener('click',e=>{if(e.target===modal)closeModal()});modal.addEventListener('cancel',()=>modalEpoch++);
function updatePreview(){const v=safeImg($('#image-url')?.value),el=$('#image-preview');if(el)el.innerHTML=v?`<img src="${E(v)}" alt="Предпросмотр" referrerpolicy="no-referrer">`:icon('image')}
function field(name,label,value='',type='text',extra=''){return `<label>${E(label)}<input name="${name}" type="${type}" value="${E(value)}" ${extra}></label>`}
function formItem(existing=null,url=''){const i=existing||cleanItem({title:'',listId:currentList()?.id,url,currency:state.settings.base});const allCats=[...new Set([...categories.map(c=>c[0]),...state.items.map(x=>x.category),i.category])];const allCurr=[...new Set([...currencies,...Object.keys(state.fx?.rates||{}),i.currency])];showModal(existing?'Редактировать желание':'Новое желание',existing?'Все поля можно изменить.':'Вставь ссылку или добавь всё вручную.',`<form id="item-form" data-id="${E(existing?.id||'')}"><label class="form-field">Ссылка на товар<div class="import-box"><input type="url" name="url" id="product-url" value="${E(i.url)}" placeholder="https://…"><button type="button" class="btn" id="import-product">${icon('sparkles')} ${existing?'Обновить данные':'Заполнить'}</button></div></label><div class="import-status" id="import-status" role="status">Вставь ссылку — попробуем получить данные автоматически.</div><div class="import-extra"><button type="button" class="btn ghost" id="import-screenshot-btn">${icon('upload')} По скриншоту</button><input type="file" id="import-screenshot" accept="image/png,image/jpeg,image/webp" hidden><button type="button" class="btn ghost" id="import-unlock">Расширенный импорт</button></div><div class="import-image-options" id="import-image-options" aria-label="Другие фото товара"></div><div class="form-grid"><label class="full">Название *<input name="title" type="text" required maxlength="250" value="${E(existing?i.title:'')}" placeholder="Например, любимая сумка"></label><div class="full image-edit"><div class="image-preview" id="image-preview"></div><div class="image-tools"><label>Ссылка на фото<input type="text" name="image" id="image-url" value="${E(i.image)}" placeholder="https://…"></label><button type="button" class="btn" id="choose-image">${icon('upload')} Загрузить фото</button><input type="file" id="image-upload" accept="image/png,image/jpeg,image/webp,image/gif" hidden><button type="button" class="btn ghost" id="clear-image">Убрать фото</button></div></div>${field('price','Цена за 1 шт.',i.price??'','number','min="0" step="0.01"') }<label>Валюта<select name="currency">${opt(allCurr,i.currency)}</select></label>${field('quantity','Количество',i.quantity,'number','min="1" max="999" step="1" required')}${field('shipping','Доставка за всё (в той же валюте)',i.shipping??'','number','min="0" step="0.01"')}<label>Категория<input name="category" type="text" list="cat-options" maxlength="80" value="${E(i.category)}" required><datalist id="cat-options">${allCats.map(c=>`<option value="${E(c)}"></option>`).join('')}</datalist></label><label>Коллекция<select name="listId">${opt([['','Без коллекции'],...state.lists.map(l=>[l.id,l.name])],i.listId)}</select></label><label class="full">Описание<textarea name="description" maxlength="5000" placeholder="Что это за вещь?">${E(i.description)}</textarea></label><div class="form-field"><span>Насколько хочется?</span><div class="rating-input" role="group" aria-label="Сила желания">${[1,2,3,4,5].map(n=>`<button type="button" data-rating="${n}" aria-label="${n} из 5" aria-pressed="${n<=i.rating}">${n<=i.rating?'♥':'♡'}</button>`).join('')}</div><input type="hidden" name="rating" value="${i.rating}"></div><label>Срочность<select name="urgency">${opt(urgency.map((x,j)=>[j+1,x]),i.urgency)}</select></label><label>Статус<select name="status">${opt(Object.entries(statuses),i.status)}</select></label>${field('date','Желаемая дата покупки',i.date,'date')}${field('variant','Размер / цвет / вариант',i.variant,'text','maxlength="200"')}${field('target','Желаемая цена',i.target??'','number','min="0" step="0.01"')}<label class="full">Личные заметки<textarea name="notes" maxlength="2000" placeholder="Например, для дня рождения…">${E(i.notes)}</textarea></label><label class="full check-line"><input type="checkbox" name="favorite" ${i.favorite?'checked':''}> В избранное</label></div></form>`,`<button class="btn" data-action="close">Отмена</button><button class="btn primary" form="item-form" type="submit">${icon('check')} Сохранить желание</button>`);updatePreview();if(url)importProduct();}
function inferCategory(t){const x=t.toLowerCase();const rules=[['Украшения',/кольц|серьг|браслет|ожерель|кулон|jewel|necklace|earring|bracelet|\bring\b/],['Красота',/космет|парфюм|духи|крем|сыворот|помад|perfume|beauty|cosmetic|skincare|lipstick|serum|makeup/],['Одежда',/плать|одежд|сумк|туфл|кроссов|куртк|брюк|пальто|ботин|dress|clothing|apparel|handbag|shoe|sneaker|coat|jacket|\bbag\b/],['Техника',/iphone|ipad|macbook|телефон|ноутбук|наушник|планшет|camera|headphone|electronics|laptop|smartphone/],['Путешествия',/путешеств|отель|билет|hotel|travel|flight|tour/],['Дом',/чашк|ваз[аы]|свеч|мебел|постель|декор|candle|furniture|home decor|mug|vase|bedding/],['Подарки',/подар|gift/]];return rules.find(([,re])=>re.test(x))?.[0]||'Другое'}
function clientParse(html,url){const doc=new DOMParser().parseFromString(html,'text/html');const meta=(...keys)=>{for(const k of keys){const m=Array.from(doc.querySelectorAll('meta')).find(e=>[e.getAttribute('property'),e.getAttribute('name'),e.getAttribute('itemprop')].includes(k));if(m?.content)return m.content}return ''};const found=[];function walk(x,d=0){if(!x||typeof x!=='object'||d>20)return;if(Array.isArray(x))return x.forEach(y=>walk(y,d+1));if([x['@type']].flat().some(t=>typeof t==='string'&&t.split('/').pop()==='Product'))found.push(x);Object.values(x).forEach(y=>walk(y,d+1))}for(const s of doc.querySelectorAll('script[type="application/ld+json"]'))try{walk(JSON.parse(s.textContent))}catch{}const p=found[0]||{},o=[p.offers].flat().find(a=>a&&typeof a==='object')||{},im=[p.image].flat()[0];let image=typeof im==='string'?im:im?.url||im?.contentUrl||meta('og:image','twitter:image');try{image=image?new URL(image,url).href:''}catch{image=''}const title=String(p.name||meta('og:title','twitter:title')||doc.title||''),description=String(p.description||meta('og:description','description')||'');const raw=o.price??o.lowPrice??o.priceSpecification?.price??meta('product:price:amount','og:price:amount','price'),currency=String(o.priceCurrency||o.priceSpecification?.priceCurrency||meta('product:price:currency','og:price:currency','priceCurrency')).toUpperCase();return {title,description,image,price:raw===''?null:num(raw),currency:/^[A-Z]{3}$/.test(currency)?currency:'',category:inferCategory([p.category,title,description].join(' ')),url}}
let importPass='';try{importPass=sessionStorage.getItem('kuklas-import-pass')||''}catch{}
function askImportPass(){const value=prompt('Введи пароль расширенного импорта (IMPORT_ACCESS_TOKEN из Netlify).');if(!value)return false;importPass=value.trim();try{sessionStorage.setItem('kuklas-import-pass',importPass)}catch{}return !!importPass}
function showImportImages(data,f){const wrap=$('#import-image-options');if(!wrap)return;wrap.replaceChildren();const values=[...new Set([data.image,...(Array.isArray(data.images)?data.images:[])].map(safeImg).filter(Boolean))].slice(0,8);if(values.length<2)return;for(const value of values){const b=document.createElement('button');b.type='button';b.className='import-thumb';b.title='Выбрать фотографию';const im=document.createElement('img');im.src=value;im.alt='Фото товара';im.referrerPolicy='no-referrer';im.loading='lazy';b.append(im);b.addEventListener('click',()=>{f.elements.image.value=value;updatePreview();[...wrap.children].forEach(x=>x.setAttribute('aria-pressed',String(x===b)))});b.setAttribute('aria-pressed',String(f.elements.image.value===value));wrap.append(b)}}
async function importProduct(options={}){
  const f=$('#item-form'),btn=$('#import-product'),message=$('#import-status'),screenBtn=$('#import-screenshot-btn');if(!f||!btn||btn.disabled)return;
  const screenshot=options.screenshot||'',raw=f.elements.url.value.trim();
  if(screenshot&&!confirm('Отправить этот скриншот в AI для распознавания? Убедись, что на нём нет личных данных.'))return;
  let url=validURL(raw);if(!url&&raw&&!/^[a-z][a-z\d+.-]*:/i.test(raw)&&/^[^\s/]+\.[^\s/]+/i.test(raw)){url=validURL('https://'+raw);if(url)f.elements.url.value=url}
  if(!url&&!screenshot){message.textContent='Введи корректную ссылку на товар.';return}
  if(url&&state.items.some(i=>i.url===url&&i.id!==f.dataset.id)&&!confirm('Такой товар уже есть. Всё равно продолжить?'))return;
  const epoch=modalEpoch;const current=()=>epoch===modalEpoch&&modal.open&&$('#item-form')===f;
  const snapshot=Object.fromEntries(new FormData(f));btn.disabled=true;if(screenBtn)screenBtn.disabled=true;
  const started=Date.now();const tick=()=>{if(current())message.textContent=screenshot?'Распознаём скриншот…':Date.now()-started<6500?'Читаем страницу магазина…':Date.now()-started<22000?'Пробуем резервные способы получения товара…':'Уточняем найденные данные…'};tick();const timer=setInterval(tick,3500);
  let data;
  const request=async()=>{const r=await fetch('/.netlify/functions/import-product',{method:'POST',headers:{'Content-Type':'application/json',...(importPass?{'X-Import-Pass':importPass}:{})},body:JSON.stringify({url:url||'',screenshot:screenshot||undefined,refresh:options.refresh===true}),signal:AbortSignal.timeout(55000)});
    const contentType=r.headers.get('content-type')||'';if(r.status===404||!contentType.includes('application/json'))throw Error('Серверный импорт не найден. Опубликуй сайт через GitHub → Netlify (не Netlify Drop) и проверь Functions.');
    const value=await r.json();if(!r.ok&&!value.requiresPass&&!value.title){const stages=(value.attempts||[]).map(x=>x.provider+': '+({ok:'данные найдены',unavailable:'недоступен',no_product:'карточка не найдена'}[x.result]||x.result)).join('; ');const disabled=value.providers&&!value.providers.firecrawl&&!value.providers.openrouter?' Firecrawl и OpenRouter не настроены в Netlify.':'';throw Error((value.error||'Ошибка импорта '+r.status)+disabled+(stages?' Проверки: '+stages+'.':''))}return value};
  try{
    data=await request();if(!current())return;
    if(data.requiresPass&&(!importPass||confirm('Расширенный импорт требует пароль. Ввести его заново?'))&&askImportPass()){data=await request();if(!current())return}
    if(!data.title)throw Error(data.error||'Карточка не найдена. Попробуй скриншот или ручной ввод.');
    if(url&&f.elements.url.value!==snapshot.url&&f.elements.url.value!==url){message.textContent='Ссылка изменена. Нажми «Заполнить» для новой ссылки.';return}
    let filled=0;const unchanged=k=>f.elements[k]&&f.elements[k].value===String(snapshot[k]??'');
    const set=(k,v)=>{if(v!==null&&v!==undefined&&v!==''&&unchanged(k)){f.elements[k].value=v;filled++}};
    set('title',data.title);set('description',data.description);set('image',safeImg(data.image)||(screenshot&&!f.elements.image.value?screenshot:''));
    if(data.price!==null&&data.price!==undefined&&/^[A-Z]{3}$/.test(data.currency||'')&&unchanged('price')&&unchanged('currency')){
      if(![...f.elements.currency.options].some(o=>o.value===data.currency))f.elements.currency.add(new Option(data.currency,data.currency));set('currency',data.currency);set('price',data.price)
    }
    if(!f.elements.category.value||f.elements.category.value==='Другое'||options.refresh)set('category',data.category&&data.category!=='Другое'?data.category:inferCategory(data.title+' '+(data.description||'')));
    if(!f.elements.variant.value)set('variant',data.variant);
    updatePreview();showImportImages(data,f);
    const missing=[];if(!f.elements.image.value)missing.push('фото');if(data.price==null||!data.currency)missing.push('цену и валюту');if(!f.elements.description.value)missing.push('описание');
    message.textContent=(filled?'Данные найдены':'Данные получены, твои изменения сохранены')+(data.source?' · '+data.source:'')+(data.cached?' · из кеша':'')+'. '+(missing.length?'Проверь или добавь вручную: '+missing.join(', ')+'.':'Проверь актуальность цены и выбранный вариант перед сохранением.');
    if(data.indexed)message.textContent+=' Часть данных найдена в поисковом индексе, цена может быть устаревшей.';if(data.requiresPass)message.textContent+=' Для улучшения результата можно повторить импорт с паролем.';
  }catch(e){if(current())message.textContent=(e.name==='TimeoutError'?'Магазин не ответил вовремя.':e.message||'Ошибка импорта.')+' Можно заполнить вручную или загрузить скриншот.'}
  finally{clearInterval(timer);if(current()){btn.disabled=false;if(screenBtn)screenBtn.disabled=false}}
}
document.addEventListener('paste',e=>{if(e.target.id!=='product-url')return;const f=$('#item-form');setTimeout(()=>{if(f&&$('#item-form')===f&&f.elements.url.value.trim())importProduct()},80)});
document.addEventListener('click',e=>{if(e.target.closest('#import-screenshot-btn'))$('#import-screenshot')?.click();if(e.target.closest('#import-unlock')){if(askImportPass()&&$('#product-url')?.value)importProduct({refresh:true})}});
document.addEventListener('change',async e=>{if(e.target.id!=='import-screenshot'||!e.target.files?.[0])return;const epoch=modalEpoch;try{const img=await resizeImage(e.target.files[0]);if(epoch!==modalEpoch)return;await importProduct({screenshot:img})}catch(err){if(epoch===modalEpoch)$('#import-status').textContent=err.message||'Не удалось прочитать скриншот'}finally{e.target.value=''}});

async function resizeImage(file){if(!file.type.startsWith('image/')||file.size>15*1024*1024)throw Error('Выбери изображение до 15 МБ.');const url=URL.createObjectURL(file);try{const im=new Image();im.src=url;await im.decode();const scale=Math.min(1,850/Math.max(im.width,im.height));const c=document.createElement('canvas');c.width=Math.max(1,Math.round(im.width*scale));c.height=Math.max(1,Math.round(im.height*scale));c.getContext('2d').drawImage(im,0,0,c.width,c.height);return c.toDataURL('image/webp',.82)}finally{URL.revokeObjectURL(url)}}
function detail(i){showModal(i.title,i.category,`<div class="detail-photo">${itemPhoto(i)}</div><div class="detail-price">${money(i.price,i.currency)}</div><div class="muted">${i.currency!==state.settings.base&&i.price!=null?(convert(i.price,i.currency)==null?'Нет курса':'≈ '+money(convert(i.price,i.currency))):''} · ${E(statuses[i.status])}</div><div class="detail-text">${E(i.description||'Описание пока не добавлено.')}</div><div class="detail-data">${[['Сила желания',`${i.rating}/5`],['Срочность',urgency[i.urgency-1]],['Коллекция',state.lists.find(l=>l.id===i.listId)?.name||'—'],['Количество',i.quantity],['Доставка',i.shipping==null?'—':money(i.shipping,i.currency)],['Итого',i.price==null?'—':money(i.price*i.quantity+(i.shipping||0),i.currency)],['Желаемая цена',i.target==null?'—':money(i.target,i.currency)],['Дата',i.date||'—'],['Размер / цвет',i.variant||'—'],['Заметки',i.notes||'—']].map(([l,v])=>`<div><small>${E(l)}</small><strong>${E(v)}</strong></div>`).join('')}</div>${i.url?`<a class="btn" href="${E(i.url)}" target="_blank" rel="noopener noreferrer">${icon('external')} Перейти в магазин</a>`:''}`,`<button class="btn danger" data-action="delete-item" data-id="${E(i.id)}">${icon('trash')} Удалить</button><button class="btn primary" data-action="edit" data-id="${E(i.id)}">${icon('edit')} Редактировать</button>`)}
function formList(l){showModal(l?'Редактировать коллекцию':'Новая коллекция','Для любимых вещей, событий и мечтаний.',`<form id="list-form" data-id="${E(l?.id||'')}"><div class="form-grid"><label class="full">Название<input name="name" type="text" required maxlength="70" value="${E(l?.name||'')}" placeholder="Например, день рождения"></label><label>Цвет<input name="color" type="color" value="${l?.color||'#e9c7cf'}"></label></div></form>`,`<button class="btn" data-action="close">Отмена</button><button class="btn primary" form="list-form" type="submit">Сохранить</button>`)}
function demo(){if(state.items.length)return;const defs=[['Красота','#f2dce7'],['Гардероб','#efdccf'],['Украшения','#e9dfc6'],['Для дома','#dfe7db']];const ls=defs.map(([name,color])=>({id:uid(),name,color}));state.lists.push(...ls);const data=[['Шёлковый топ в молочном цвете','Одежда',5900,'RUB',4,3,1],['Парфюм с нотами ванили','Красота',95,'USD',5,4,0],['Минималистичные серьги','Украшения',120,'EUR',5,2,2],['Керамическая чашка','Дом',2300,'RUB',3,1,3],['Маленькая кожаная сумка','Одежда',8600,'RUB',5,5,1],['Нежная ароматическая свеча','Дом',3200,'RUB',4,2,3]];state.items=data.map(([title,category,price,currency,rating,urgency,l],n)=>cleanItem({title,category,price,currency,rating,urgency,listId:ls[l].id,favorite:rating===5,description:'Демонстрационная карточка, не реальное предложение магазина.',demo:true,created:Date.now()-n}));save();render();toast('Пример добавлен')}
function removeDemo(){const ids=new Set(state.items.filter(i=>i.demo).map(i=>i.listId));state.items=state.items.filter(i=>!i.demo);state.lists=state.lists.filter(l=>!ids.has(l.id)||state.items.some(i=>i.listId===l.id));save();if(currentList()||page.startsWith('list:'))go('home');else render();toast('Пример удалён')}
function downloadJSON(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='kuklas-wishes-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('Резервная копия сохранена')}
function encode(o){const b=new TextEncoder().encode(JSON.stringify(o));let s='';for(let n=0;n<b.length;n+=8192)s+=String.fromCharCode(...b.subarray(n,n+8192));return btoa(s).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'')}
function decode(s){return JSON.parse(new TextDecoder().decode(Uint8Array.from(atob(s.replace(/-/g,'+').replace(/_/g,'/')),c=>c.charCodeAt(0))))}
function share(){const scoped=page==='home'||page==='settings'||page==='stats'||page==='collections'?state.items.filter(i=>i.status!=='bought'):sourceItems();const items=scoped.map(i=>({...i,notes:'',image:i.image.startsWith('data:')?'':i.image,demo:false}));const lists=state.lists.filter(l=>items.some(i=>i.listId===l.id));const payload=encode({version:1,items,lists,settings:{base:state.settings.base}});const url=location.origin+location.pathname+'#share='+payload;showModal('Поделиться желаниями','Снимок текущего списка — без личных заметок и загруженных с устройства фото.',`<p class="muted">Получатель сможет посмотреть и сохранить копию списка. Изменения в оригинале не обновляют эту ссылку. Любой, у кого есть ссылка, может прочитать её содержимое. ${items.length} желаний.</p>${url.length>12000?'<div class="notice">Список слишком большой для надёжной передачи ссылкой. Используй экспорт JSON (включает личные заметки).</div>':`<label class="form-field">Ссылка<textarea id="share-url" readonly rows="4">${E(url)}</textarea></label>`}`,`<button class="btn" data-action="export">Экспорт JSON</button>${url.length<=12000?'<button class="btn primary" data-action="copy-share">Копировать ссылку</button>':''}`)}
function openShared(){if(!location.hash.startsWith('#share='))return false;try{const raw=location.hash.slice(7);if(raw.length>12000)throw Error('Ссылка слишком большая');const s=normalize(decode(raw));page='home';render();showModal('Тебе поделились желаниями',`${s.items.length} желаний · снимок списка`,`${s.items.length?s.items.map(i=>`<div class="collection-manage"><span class="list-dot" style="background:${catInfo(i.category)[2]}"></span><strong>${E(i.title)}</strong><small>${money(i.price,i.currency)}</small>${i.url?`<a class="icon-btn" href="${E(i.url)}" target="_blank" rel="noopener noreferrer" aria-label="Открыть товар">${icon('external')}</a>`:''}</div>`).join(''):'<p>Список пуст.</p>'}`,`<button class="btn" data-action="close">Закрыть</button><button class="btn primary" data-action="accept-share">Добавить копию</button>`);$('#modal-content')._shared=s;return true}catch{toast('Не удалось открыть ссылку');history.replaceState(null,'','#home');return false}}
function mutate(i,fn){const action=document.activeElement?.dataset?.action;fn(i);i.updated=Date.now();save();render();if(action){const next=$$('[data-action][data-id]').find(b=>b.dataset.id===i.id&&b.dataset.action===action);(next||$('#search')||$('#main-content'))?.focus({preventScroll:true});}}
document.addEventListener('click',async e=>{const rating=e.target.closest('[data-rating]');if(rating){const v=Number(rating.dataset.rating);$('#item-form').elements.rating.value=v;$$('[data-rating]').forEach(b=>{const on=Number(b.dataset.rating)<=v;b.textContent=on?'♥':'♡';b.setAttribute('aria-pressed',String(on))});return}const nav=e.target.closest('[data-page]');if(nav){go(nav.dataset.page);return}const chip=e.target.closest('[data-category]');if(chip){category=chip.dataset.category;$$('[data-category]').forEach(x=>{const active=x.dataset.category===category;x.classList.toggle('active',active);x.setAttribute('aria-pressed',String(active))});renderProducts();return}const a=e.target.closest('[data-action]');if(a){const action=a.dataset.action,i=state.items.find(x=>x.id===a.dataset.id),l=state.lists.find(x=>x.id===a.dataset.id);switch(action){case'add':formItem();break;case'close':closeModal();break;case'detail':if(i)detail(i);break;case'edit':if(i)formItem(i);break;case'favorite':if(i)mutate(i,x=>x.favorite=!x.favorite);break;case'toggle-bought':if(i){mutate(i,x=>x.status=x.status==='bought'?'wish':'bought');toast(i.status==='bought'?'Маленькая мечта сбылась! ♡':'Возвращено в желания')}break;case'delete-item':if(i&&confirm('Удалить это желание?')){state.items=state.items.filter(x=>x.id!==i.id);save();closeModal();render();toast('Желание удалено')}break;case'new-list':formList();break;case'edit-list':if(l)formList(l);break;case'delete-list':if(l&&confirm('Удалить коллекцию? Желания останутся в общем списке.')){state.lists=state.lists.filter(x=>x.id!==l.id);state.items.forEach(i=>{if(i.listId===l.id)i.listId=''});save();go('collections');render()}break;case'fx':a.disabled=true;await refreshFX();a.disabled=false;break;case'view-grid':case'view-list':state.settings.view=action==='view-grid'?'grid':'list';save();render();break;case'reset-filters':query='';category='';statusFilter='';render();break;case'demo':demo();break;case'remove-demo':removeDemo();break;case'export':downloadJSON();break;case'import-backup':$('#backup-input').click();break;case'share':share();break;case'copy-share':try{await navigator.clipboard.writeText($('#share-url').value);toast('Ссылка скопирована')}catch{$('#share-url').select();toast('Скопируй выделенную ссылку вручную')}break;case'accept-share':{const s=$('#modal-content')._shared;if(!s)break;const m=new Map();s.lists.forEach(l=>{const id=uid();m.set(l.id,id);state.lists.push({...l,id})});s.items.forEach(i=>state.items.push({...i,id:uid(),listId:m.get(i.listId)||'',created:Date.now()}));save();closeModal();history.replaceState(null,'','#home');render();toast('Копия списка добавлена');break}case'clear':if(confirm('Удалить все желания и коллекции? Это действие нельзя отменить.')){state.items=[];state.lists=[];save();render();toast('Список очищен')}break}return}if(e.target.closest('#top-add'))formItem();else if(e.target.closest('#top-share'))share();else if(e.target.closest('#new-list'))formList();else if(e.target.closest('#import-product'))importProduct({refresh:!!$('#item-form')?.dataset.id});else if(e.target.closest('#choose-image'))$('#image-upload').click();else if(e.target.closest('#clear-image')){$('#image-url').value='';updatePreview()}});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;renderProducts()}if(e.target.id==='image-url')updatePreview()});
document.addEventListener('change',async e=>{const el=e.target;if(el.id==='sort'){sort=el.value;renderProducts()}if(el.id==='group'){group=el.value;renderProducts()}if(el.id==='status-filter'){statusFilter=el.value;renderProducts()}if(el.id==='image-upload'&&el.files[0]){const epoch=modalEpoch;try{const v=await resizeImage(el.files[0]);if(epoch===modalEpoch){$('#image-url').value=v;updatePreview()}}catch(err){toast(err.message||'Не удалось прочитать фото')}}if(el.id==='backup-input'&&el.files[0]){try{if(el.files[0].size>20*1024*1024)throw Error('Файл слишком большой');const s=normalize(JSON.parse(await el.files[0].text()));if(confirm(`Заменить текущие данные? В файле ${s.items.length} желаний.`)){state=s;save();go('home');render();toast('Резервная копия восстановлена')}}catch(err){toast('Не удалось импортировать файл: '+err.message)}el.value=''}});
document.addEventListener('submit',e=>{const f=e.target;if(!['quick-form','item-form','list-form','settings-form'].includes(f.id))return;e.preventDefault();const d=Object.fromEntries(new FormData(f));if(f.id==='quick-form'){formItem(null,d.url);return}if(f.id==='item-form'){if(!d.title.trim()){toast('Укажи название');return}if(d.url&&!validURL(d.url)){toast('Проверь ссылку');return}if(d.image&&!safeImg(d.image)){toast('Проверь ссылку на фото или загрузи изображение');return}const old=state.items.find(i=>i.id===f.dataset.id);const item=cleanItem({...old,...d,title:d.title.trim(),category:d.category.trim()||'Другое',favorite:d.favorite==='on',demo:false,updated:Date.now()});if(old)state.items[state.items.indexOf(old)]=item;else state.items.unshift(item);const ok=save();closeModal();render();if(ok)toast(old?'Изменения сохранены':'Желание добавлено ♡');return}if(f.id==='list-form'){if(!d.name.trim())return;const l=state.lists.find(x=>x.id===f.dataset.id);if(l){l.name=d.name.trim();l.color=d.color}else state.lists.push({id:uid(),name:d.name.trim(),color:d.color});save();closeModal();render();toast('Коллекция сохранена');return}if(f.id==='settings-form'){const oldBase=state.settings.base;state.settings.name=d.name.trim();state.settings.base=d.base;state.settings.budget=oldBase!==d.base&&String(state.settings.budget??'')===d.budget?null:num(d.budget);save();render();toast('Настройки сохранены')}});
document.addEventListener('error',e=>{if(e.target.tagName==='IMG'){const img=e.target;const p=img.parentElement;if(!p)return;const span=document.createElement('span');span.className='placeholder';span.innerHTML=icon('image');img.replaceWith(span)}},true);
$('.skip-link').addEventListener('click',e=>{e.preventDefault();$('#main-content').focus();$('#main-content').scrollIntoView({block:'start'});});
window.addEventListener('hashchange',()=>{if(!openShared())route()});hydrate();if(!openShared())route();if(!state.fx||Date.now()-state.fx.date>24*3600*1000)refreshFX(true);
